import { DatePipe, NgClass } from '@angular/common';
import { Component, Input, SimpleChanges } from '@angular/core';
import { UtilsService } from '../../services/utils.service';
import { TitlecasePipe } from '../../pipes/titlecase.pipe';
import { FormularioFlotanteComponent } from "../formulario-flotante/formulario-flotante.component";
import { RouterLink } from '@angular/router';

export type BootstrapClass ='primary'|'secondary'|'success'|'warning'|'info'|'danger'|'dark'|'light'|'white'

@Component({
    selector: 'data-view-section',
    imports: [
    NgClass,
    TitlecasePipe,
    RouterLink
],
    templateUrl: './data-view.component.html',
    styleUrl: './data-view.component.css',
    providers: [
        DatePipe,
    ]
})
export class DataViewSectionComponent {
  @Input() data?:any|(any[])={}
  @Input() title?:string=''
  @Input() ignoreNumbers:boolean=false
  @Input() keys:string[]=[]
  @Input() nullString='N/A'
  @Input() dateFormat:string='dd/MM/yyyyYY'
  @Input() zonaHoraria ="UTC"
  @Input() bootstrapClass:BootstrapClass='primary'
  @Input() expanded:boolean=true
  @Input() editarRoute?:string
  @Input() divClass:string='container-fluid p-3'
  @Input() sticky?:boolean=false
  @Input() ignoreKeys:string[]=[]
  @Input() emptyMsj:string='No hay datos registrados.'
  @Input() urlKey?:string
  @Input() disabled:boolean = false;

  constructor(
    public utils: UtilsService,
    private datePipe: DatePipe,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['data'] && this.keys.length==0){
      this.setKeys()
    }
  }

  setKeys() {
    if (!this.data) return;
  
    if (Array.isArray(this.data) && this.data.length > 0) {
      this.keys = Object.keys(this.data[0]).filter(key => !this.ignoreKeys.includes(key));
      return;
    }
  
    this.keys = Object.keys(this.data).filter(key => !this.ignoreKeys.includes(key) && !this.isIgnored(key) );
  }

  isIgnored(key:string){
    if(this.isArray(this.data)){
      return this.isIgnoredInArray(key)
    }
    return this.isIgnoredValue(key,this.data)
  }

  isIgnoredInArray(key:string):boolean{
    if(!this.isArray(this.data)) return false
    return this.data.some((row)=> this.isIgnoredValue(key,row))
  }

  isIgnoredValue(key:string,data:any):boolean{
    if(data===null || data===undefined) return false
    if(this.ignoreNumbers && this.utils.isNumber(data[key]) && key!=='id') return true
    const type= typeof data[key]
    if(Array.isArray(data)) return true
    if(type=='object' && data[key]?.nombre )  return false
    if(type=='object') return true
    if(type =='function') return true
    return false
  }

  valueOf(value:any):string{
    if(value==='INNE') return 'INE'
    if(value===null|| value==undefined|| value=='') return this.nullString
    if(value.nombre){
      return value.nombre
    }
    if(this.utils.isISODateString(value)){
      return this.utils.fechaFormateada(value, true) ??'N/A'
    }
    return value
  }

  valueBySubKeys(value: string) {
    const keys = value.split('.');
    if (Array.isArray(this.data)) return this.nullString;
    console.info(value)

    let currentValue = this.data;
    for (const key of keys) {
      if (currentValue === null || currentValue === undefined) {
        return this.nullString;
      }
      currentValue = currentValue[key];
    }

    return this.valueOf(currentValue);
  }

  isArray(data:any):data is any[]{
    if(!data)return false
    return (data as any[]).length!==undefined
  }
}
